<script setup>
import { computed, inject, ref } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import MetricCard from '../components/MetricCard.vue'
import CompressionDetailDialog from '../components/CompressionDetailDialog.vue'
import { uiContextKey } from '../ui/context.js'
import { appOptions, getMockFiles, mockApps } from '../ui/mock-data.js'
import { compressionStatusLabels,formatBytes } from '../top50.js'
const { previewAppId }=inject(uiContextKey,{previewAppId:ref('10350')})
const status=ref('ALL'),startDate=ref('2026-10-01'),endDate=ref('2026-10-13'),sort=ref('benefit'),file=ref(null),notice=ref('')
const app=computed(()=>mockApps[previewAppId.value])
const items=computed(()=>{
  const rows=getMockFiles(previewAppId.value).filter(item=>status.value==='ALL'||item.compressionStatus===status.value)
  return rows.sort((a,b)=>sort.value==='size' ? Number(b.fileSizeBytes)-Number(a.fileSizeBytes) : sort.value==='traffic' ? Number(b.predictedBytes)-Number(a.predictedBytes) : Number(b.uiEstimatedBenefit.replaceAll(',',''))-Number(a.uiEstimatedBenefit.replaceAll(',','')))
})
</script>
<template><div data-page="compression"><header class="page-heading"><div><h1>压缩降本决策</h1><p>结合热点文件、压缩空间与成本证据，区分预测收益和实际效果。</p></div><span class="source-badge">UI MOCK · 静态演示</span></header>
  <section class="card filter-card"><div class="filter-field"><label for="compression-app">AppID</label><select id="compression-app" v-model="previewAppId"><option v-for="option in appOptions" :key="option.id" :value="option.id">{{ option.label }}</option></select></div><div class="filter-field"><label for="compression-status">压缩状态</label><select id="compression-status" v-model="status"><option value="ALL">全部状态</option><option value="PENDING">待处理</option><option value="PROCESSING">处理中</option><option value="COMPRESSED">已压缩 · 样例</option></select></div><div class="filter-field"><label for="compression-start">日期范围</label><div class="date-range"><input id="compression-start" v-model="startDate" type="date" aria-label="压缩查询开始日期"><span class="date-separator">—</span><input v-model="endDate" type="date" aria-label="压缩查询结束日期"></div></div><div class="filter-field filter-spacer"><label for="compression-sort">排序</label><select id="compression-sort" v-model="sort"><option value="benefit">预计净收益降序</option><option value="traffic">预测流量降序</option><option value="size">文件大小降序</option></select></div></section>
  <div class="context-note"><span>App {{ previewAppId }} · {{ startDate }} — {{ endDate }} · 日期仅为 UI 筛选配置，未查询效果记录</span><span>预计值为固定情景样例</span></div>
  <section class="metric-grid metric-grid--five"><MetricCard label="可压缩文件数" :value="app.pending" unit="个" icon="compression" note="UI 示例数量"/><MetricCard label="预计节省流量" :value="app.savedTraffic" unit="TB" icon="file" note="预测情景 · UI Mock"/><MetricCard label="预计节省金额" :value="`¥ ${app.forecastSaving}`" icon="money" tone="green" note="估算样例，非实际账单"/><MetricCard label="已完成压缩数" :value="app.completed" unit="个" icon="check" note="UI 示例，未实际登记"/><MetricCard label="实际节省金额" value="—" icon="money" tone="green" note="待真实观测与成本核验"/></section>
  <div v-if="notice" class="notice notice--amber" role="status"><AppIcon name="info" :size="16"/>{{ notice }}</div>
  <section class="card table-card"><header class="card-heading"><div><h2>压缩推荐列表</h2><p class="compression-table-copy">按预计净收益与流量价值查看文件，样例处理状态仅用于界面展示。</p></div><span class="sample-bullet">{{ items.length }} 条 UI 样例</span></header><div class="table-scroll"><table><thead><tr><th>文件路径（FileKey）</th><th>文件大小</th><th>预测流量</th><th>预计压缩率</th><th>预计净收益</th><th>当前状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.fileKey"><td><div class="file-key" :title="item.fileKey">{{ item.fileKey }}</div><small class="file-subtitle">App {{ item.appId }} · UI Mock</small></td><td>{{ formatBytes(item.fileSizeBytes) }}</td><td>{{ formatBytes(item.predictedBytes) }}</td><td><div class="ratio-display"><span>{{ item.uiCompressionRatio }}</span><i><b :style="{width:item.uiCompressionRatio}"/></i></div></td><td><strong class="benefit-number">¥ {{ item.uiEstimatedBenefit }}</strong></td><td><span class="status-pill" :class="`status-pill--${item.compressionStatus.toLowerCase()}`">{{ compressionStatusLabels[item.compressionStatus] }}</span></td><td><div class="row-actions"><button class="text-button" @click="file=item">查看详情</button><button class="text-button" @click="notice='压缩登记尚未接入，未修改任何文件状态或保存业务记录。'">{{ item.compressionStatus==='COMPRESSED' ? '处理记录' : '标记压缩' }} <span class="operation-hint">未接入</span></button></div></td></tr></tbody></table></div><footer class="table-footer"><span>UI Mock 数据按状态和排序控件展示，不代表真实推荐服务。</span><span>预计净收益与实际收益独立展示</span></footer></section>
  <div class="compression-info-grid"><section class="card"><header class="card-heading"><h2>从推荐到效果追踪</h2><span class="source-badge source-badge--muted">业务流程示意</span></header><div class="compression-steps"><div><span>1</span><strong>查看候选文件</strong><small>流量、大小与压缩空间</small></div><AppIcon name="chevron" :size="14"/><div><span>2</span><strong>登记处理结果</strong><small>版本、质量与大小证据</small></div><AppIcon name="chevron" :size="14"/><div><span>3</span><strong>观察实际效果</strong><small>访问承接与成本核验</small></div></div></section><section class="card compression-evidence"><AppIcon name="info" :size="24"/><div><h3>实际收益需要证据支持</h3><p>没有成熟观测、质量与成本记录时，实际节省保持未知，不能用体积差或预测金额替代。</p><span class="status-pill status-pill--unknown">当前未接入效果追踪</span></div></section></div>
  <CompressionDetailDialog :file="file" @close="file=null"/>
</div></template>
<style scoped>.compression-table-copy{font-size:10px;color:#91a3ba;margin:8px 0 1px}.ratio-display{display:flex;flex-direction:column;gap:7px;font-size:11px;color:#6e8caa}.ratio-display>i{width:65px;height:4px;border-radius:3px;background:#eaf2fc;overflow:hidden}.ratio-display b{display:block;height:100%;background:#76b5ff;border-radius:3px}.benefit-number{color:#28977b;font-size:12px;font-weight:550}.operation-hint{font-size:8px;color:#a1aebf}.compression-info-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:18px;margin-top:18px}.compression-steps{display:flex;align-items:center;justify-content:space-around;padding:10px 20px 26px;gap:15px}.compression-steps>div{display:flex;align-items:center;flex-direction:column;gap:8px;text-align:center}.compression-steps>div>span{background:#edf5ff;color:#1677ff;width:28px;height:28px;display:grid;place-items:center;border-radius:50%;font-size:11px;margin-bottom:4px}.compression-steps strong{font-size:11px;color:#6a85a7;font-weight:500}.compression-steps small{font-size:9px;color:#a1afc0}.compression-steps>svg{color:#b9c8dc}.compression-evidence{display:flex;align-items:flex-start;gap:15px;padding:24px;color:#80a8da}.compression-evidence h3{font-size:13px;color:#5a769a;font-weight:550}.compression-evidence p{font-size:11px;color:#8ea1b9;line-height:1.9}.compression-evidence>.svg{flex:none}.compression-info-grid .card-heading{margin-bottom:6px}@media(max-width:1200px){.compression-info-grid{grid-template-columns:1fr}.compression-steps{justify-content:center;gap:30px}}@media(max-width:760px){.compression-steps{gap:12px;padding-left:12px;padding-right:12px}.compression-steps small{font-size:8px}.context-note{flex-wrap:wrap}}</style>
